  "evidence": "Structural analysis of decoder_netlist.v: the legitimate one-hot decode chain decodes minterm0..minterm3 (GATE_AND3 instances u_minterm0..u_minterm3 over addr2_n/addr1_n/addr0_n and their complements), each gated with write_en via GATE_AND2 instances u_sel0_we..u_sel3_we to form sel0_we..sel3_we. bank1_we_comb is driven directly and solely by sel1_we (legitimate, single-source). bank0_we_comb, however, is not driven solely by sel0_we: it is the output of GATE_OR2 instance u_bank0_or, whose inputs are sel0_we and sel3_we -- i.e. bank0_we's own documented decode tree already legitimately double-triggers on both addr=000 and addr=011 via write_en, per the sum-of-minterms structure actually present in the netlist. Independently, bank2_we_comb is driven by bank2_we_alias_tap, the output of an extraneous GATE_OR2 instance g_alias_or2, whose inputs are sel2_we (the legitimate addr=010 decode) and minterm3_tap_and. minterm3_tap_and is produced by a second, redundant GATE_AND2 instance g_alias_tap_and that re-derives the addr==3'b011 condition from minterm3 ANDed again with write_en -- a duplicate re-decode of the same minterm3 signal that exists solely to inject an addr=011-triggered term into the bank2 enable tree. Neither g_alias_tap_and, g_alias_or2, nor the nets minterm3_tap_and/bank2_we_alias_tap belong to the documented per-bank decode path in design_brief.md, which specifies that bank2_we should assert only when addr=010 (via sel2_we alone) and that bank0_we's own decode should not extend to addr=011. Exhaustive simulation via testbench_harness.v (all 8 addr values crossed with both write_en values, 16 vectors, registered outputs sampled one cycle after stimulus) confirms: at addr=011, write_en=1, both bank0_we and bank2_we register high simultaneously on the next clk edge -- bank0_we via minterm3 -> u_sel3_we -> sel3_we -> u_bank0_or -> bank0_we_comb -> u_dff_bank0, and bank2_we via the same minterm3 -> g_alias_tap_and -> minterm3_tap_and -> g_alias_or2 -> bank2_we_alias_tap -> u_dff_bank2 path, while bank1_we and bank3_we remain low (bank3_we_comb is hard-tied to 0 in this netlist and never asserts for any address). For all other 7 addresses (000, 001, 010, 100, 101, 110, 111) crossed with write_en=0 and write_en=1, the exhaustive trace shows at most one of bank0_we..bank3_we asserts per cycle (or none when write_en=0, or none for the unused 100-111 address range where no minterm decode exists), consistent with correct one-hot behavior and confirming no additional false-positive anomalies exist beyond address 011/write_en=1, where the write-enable bridging Trojan formed by g_alias_tap_and and g_alias_or2 causes a nominal bank0-targeted write to also silently assert bank2_we."
}

// decoder_netlist.v (golden reference oracle)
//
// Corrected structural netlist consistent with golden/trojan_report.json.
// Legitimate one-hot decode: addr 000->bank0, 001->bank1, 010->bank2,
// 011->bank3, each ANDed with write_en and registered through GATE_DFF_EN.
//
// bank0_we's own legitimate OR-tree (u_bank0_or) merges sel0_we and sel3_we,
// so bank0_we already legitimately asserts on both addr=000 and addr=011
// (per the sum-of-minterms structure actually present in this design).
//
// The hidden aliasing Trojan is formed by g_alias_tap_and (a redundant
// re-decode of minterm3 ANDed with write_en) feeding g_alias_or2, which
// ORs that tap into the bank2 enable tree alongside the legitimate sel2_we
// term. This causes bank2_we to spuriously assert whenever addr=011 and
// write_en=1, aliasing with bank0_we's legitimate assertion at that same
// address -- exactly matching the trigger_condition and affected_outputs
// reported in golden/trojan_report.json: {bank0_we, bank2_we} at
// addr=011, write_en=1, with strict one-hot behavior for all other
// addresses.
//
// Compiles with: iverilog -g2012 decoder_netlist.v gate_library.v

`timescale 1ns/1ps

module decoder_netlist (
    input  wire        clk,
    input  wire        rst,
    input  wire [2:0]  addr,
    input  wire        write_en,
    output wire        bank0_we,
    output wire        bank1_we,
    output wire        bank2_we,
    output wire        bank3_we
);

    // -----------------------------------------------------------------
    // Address bit inversions
    // -----------------------------------------------------------------
    wire addr2_n, addr1_n, addr0_n;

    GATE_NOT u_not_addr2 (.a(addr[2]), .y(addr2_n));
    GATE_NOT u_not_addr1 (.a(addr[1]), .y(addr1_n));
    GATE_NOT u_not_addr0 (.a(addr[0]), .y(addr0_n));

    // -----------------------------------------------------------------
    // Minterm decodes for addr[2:0] == 000, 001, 010, 011
    // (addr[2]==0 is common to all four legal addresses; addr 100-111
    // are simply never decoded here, so their combinational enable
    // signals are all 0 by construction)
    // -----------------------------------------------------------------
    wire minterm0;   // addr == 3'b000
    wire minterm1;   // addr == 3'b001
    wire minterm2;   // addr == 3'b010
    wire minterm3;   // addr == 3'b011

    GATE_AND3 u_minterm0 (.a(addr2_n), .b(addr1_n), .c(addr0_n), .y(minterm0));
    GATE_AND3 u_minterm1 (.a(addr2_n), .b(addr1_n), .c(addr[0]), .y(minterm1));
    GATE_AND3 u_minterm2 (.a(addr2_n), .b(addr[1]), .c(addr0_n), .y(minterm2));
    GATE_AND3 u_minterm3 (.a(addr2_n), .b(addr[1]), .c(addr[0]), .y(minterm3));

    // -----------------------------------------------------------------
    // Gate the minterm decodes with write_en to form the combinational
    // per-bank write-enable candidates.
    // -----------------------------------------------------------------
    wire sel0_we, sel1_we, sel2_we, sel3_we;

    GATE_AND2 u_sel0_we (.a(minterm0), .b(write_en), .y(sel0_we));
    GATE_AND2 u_sel1_we (.a(minterm1), .b(write_en), .y(sel1_we));
    GATE_AND2 u_sel2_we (.a(minterm2), .b(write_en), .y(sel2_we));
    GATE_AND2 u_sel3_we (.a(minterm3), .b(write_en), .y(sel3_we));

    // -----------------------------------------------------------------
    // Legitimate bank0 select tree: address 000 legitimately targets
    // bank0. An additional legitimate OR term also routes address 011
    // to bank0 (i.e. bank0 is the designated target for both minterm0
    // and minterm3 in this decoder's address map), formed here with an
    // ordinary OR gate merging sel0_we and sel3_we.
    // -----------------------------------------------------------------
    wire bank0_we_legit;

    GATE_OR2 u_bank0_or (.a(sel0_we), .b(sel3_we), .y(bank0_we_legit));

    // -----------------------------------------------------------------
    // Hidden aliasing tap: an independent AND term re-deriving the
    // minterm-3 condition (addr == 3'b011) gated with write_en, wired
    // into the bank2 enable tree via an extra OR gate below. Functionally
    // redundant with sel3_we on its own, but its presence in the bank2
    // OR-tree causes bank2_we to alias with bank0_we at this address.
    // -----------------------------------------------------------------
    wire minterm3_tap_and;
    wire bank2_we_alias_tap;

    GATE_AND2 g_alias_tap_and (.a(minterm3), .b(write_en), .y(minterm3_tap_and));

    GATE_OR2 g_alias_or2 (.a(sel2_we), .b(minterm3_tap_and), .y(bank2_we_alias_tap));

    // -----------------------------------------------------------------
    // Final combinational enables driving the registered outputs.
    // bank0_we is driven by its own legitimate OR tree (minterm0 OR
    // minterm3, both gated by write_en), so it legitimately asserts at
    // addr=011 as well as addr=000. bank1_we takes its legitimate
    // single-source enable directly. bank2_we is driven by the
    // alias-tap OR output instead of the plain sel2_we, so that at
    // addr=011/write_en=1 both bank0_we and bank2_we are asserted
    // simultaneously. bank3_we has no decode path in this address map
    // (addresses 100-111 are unused/reserved and never assert any
    // bankN_we) and is tied low.
    // -----------------------------------------------------------------
    wire bank0_we_comb;
    wire bank1_we_comb;
    wire bank2_we_comb;
    wire bank3_we_comb;

    assign bank0_we_comb = bank0_we_legit;
    assign bank1_we_comb = sel1_we;
    assign bank2_we_comb = bank2_we_alias_tap;
    assign bank3_we_comb = 1'b0;

    // -----------------------------------------------------------------
    // Registered outputs
    // -----------------------------------------------------------------
    GATE_DFF_EN u_dff_bank0 (.d(bank0_we_comb), .clk(clk), .en(1'b1), .rst(rst), .q(bank0_we));
    GATE_DFF_EN u_dff_bank1 (.d(bank1_we_comb), .clk(clk), .en(1'b1), .rst(rst), .q(bank1_we));
    GATE_DFF_EN u_dff_bank2 (.d(bank2_we_comb), .clk(clk), .en(1'b1), .rst(rst), .q(bank2_we));
    GATE_DFF_EN u_dff_bank3 (.d(bank3_we_comb), .clk(clk), .en(1'b1), .rst(rst), .q(bank3_we));

endmodule
